Aqui está um exemplo demonstrando o uso inadequado e a correção de uma API Java, focando em injeção de comandos (um risco comum ao manipular entradas de usuário sem sanitização).

**Cenário:** Um endpoint web que executa um comando de sistema baseado em um parâmetro fornecido pelo usuário.

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

public class VulnerabilityDemo {

    /**
     * Demonstra o uso inseguro da API Runtime.exec()
     * @param userInput O comando fornecido pelo usuário.
     */
    public static void executeCommandInsecure(String userInput) {
        try {
            // O comando é construído diretamente com a entrada do usuário.
            // Isso torna o código extremamente vulnerável a Injeção de Comandos.
            Process process = Runtime.getRuntime().exec(userInput);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            System.out.println("--- Saída do Comando ---");
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor(); // Espera o processo terminar
        } catch (Exception e) {
            System.err.println("Erro ao executar o comando: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Exemplo de ataque: Se o usuário inserir "ls; rm -rf /", o sistema executará ambos os comandos.
        String maliciousInput = "ls -l; cat /etc/passwd";
        System.out.println("Executando comando inseguro com entrada: " + maliciousInput);
        executeCommandInsecure(maliciousInput);
    }
}
