import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.List;

public class SecureDemo {

    /**
     * Demonstra o uso seguro da API Runtime.exec() passando argumentos como uma lista.
     * @param command O comando base (ex: "ls").
     * @param args Os argumentos do comando (ex: "-l").
     */
    public static void executeCommandSecure(String command, String... args) {
        try {
            // Ao passar o comando e seus argumentos como um array de strings (List/String[]),
            // o Java trata cada elemento como um argumento separado, prevenindo a injeção de comandos.
            ProcessBuilder pb = new ProcessBuilder(command);
            pb.command().addAll(Arrays.asList(args));

            Process process = pb.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            System.out.println("--- Saída do Comando Seguro ---");
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor(); // Espera o processo terminar
        } catch (Exception e) {
            System.err.println("Erro ao executar o comando: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Exemplo seguro: O argumento "ls -l; cat /etc/passwd" será tratado como um único argumento
        // para o comando 'ls', e não como um comando separado.
        String safeCommand = "ls";
        String[] safeArgs = {"-l"};

        System.out.println("Executando comando seguro com argumentos: " + Arrays.toString(safeArgs));
        executeCommandSecure(safeCommand, safeArgs);
    }
}
